// Decodes the FIRST page of a TIFF and downscales it to a thumbnail-sized PNG,
// entirely off the main thread. UTIF's decode, the RGBA conversion, the resize,
// and the PNG encode are all synchronous CPU — running them here keeps a grid of
// TIFF thumbnails from janking the UI. We only ever touch ifds[0], so a 200-page
// scan costs the same as a one-page one.
import UTIF from "utif";

interface Ifd {
  t256?: number[];
  t257?: number[];
  width?: number;
  height?: number;
}
interface Utif {
  decode(buf: ArrayBuffer): Ifd[];
  decodeImage(buf: ArrayBuffer, ifd: Ifd): void;
  toRGBA8(ifd: Ifd): Uint8Array;
}
const utif = UTIF as Utif;

interface Req {
  id: number;
  buffer: ArrayBuffer;
  targetWidth: number;
}

const ctx = self as unknown as Worker;

ctx.onmessage = async (event: MessageEvent<Req>) => {
  const { id, buffer, targetWidth } = event.data;
  try {
    const ifds = utif.decode(buffer);
    if (!ifds.length) throw new Error("TIFF has no frames");
    const ifd = ifds[0];
    utif.decodeImage(buffer, ifd);
    const rgba = utif.toRGBA8(ifd);
    const width = ifd.t256?.[0] ?? ifd.width ?? 0;
    const height = ifd.t257?.[0] ?? ifd.height ?? 0;
    if (!width || !height) throw new Error("TIFF has no dimensions");

    const dw = Math.min(width, targetWidth);
    const dh = Math.max(1, Math.round((dw / width) * height));
    const pixels = new Uint8ClampedArray(rgba.length);
    pixels.set(rgba);
    const source = new ImageData(pixels, width, height);
    const bitmap = await createImageBitmap(source, {
      resizeWidth: dw,
      resizeHeight: dh,
      resizeQuality: "high",
    });
    const canvas = new OffscreenCanvas(dw, dh);
    const c = canvas.getContext("2d");
    if (!c) throw new Error("No 2d context");
    c.drawImage(bitmap, 0, 0);
    bitmap.close();
    const blob = await canvas.convertToBlob({ type: "image/png" });
    ctx.postMessage({ id, ok: true, blob });
  } catch (err) {
    ctx.postMessage({
      id,
      ok: false,
      error: err instanceof Error ? err.message : String(err),
    });
  }
};

// Parses the first rows of a spreadsheet's first sheet off the main thread.
// XLSX.read is fully synchronous CPU and was the largest UI-thread block of the
// thumbnail grid; running it here keeps the page responsive. `sheetRows` stops
// the parser early so a 100k-row workbook costs the same as a 16-row one.
import * as XLSX from "@e965/xlsx";

import { isSpreadsheetContainer } from "@/lib/xlsx-worker-protocol";

interface Req {
  id: number;
  buffer: ArrayBuffer;
  maxRows: number;
  maxCols: number;
}

const ctx = self as unknown as Worker;

ctx.onmessage = (event: MessageEvent<Req>) => {
  const { id, buffer, maxRows, maxCols } = event.data;
  try {
    // SheetJS sniffs arbitrary bytes into a stub sheet; reject non-spreadsheet
    // input so a mislabeled file yields no thumbnail rather than junk cells.
    if (!isSpreadsheetContainer(buffer)) {
      throw new Error("File is not a recognized spreadsheet (.xlsx or .xls).");
    }
    const wb = XLSX.read(new Uint8Array(buffer), {
      type: "array",
      sheetRows: maxRows,
    });
    const ws = wb.Sheets[wb.SheetNames[0]];
    const grid = XLSX.utils.sheet_to_json<string[]>(ws, {
      header: 1,
      blankrows: false,
      defval: "",
      raw: false,
    });
    const rows = grid
      .slice(0, maxRows)
      .map((r) =>
        Array.isArray(r) ? r.slice(0, maxCols).map((c) => `${c ?? ""}`) : [],
      );
    ctx.postMessage({ id, ok: true, rows });
  } catch (err) {
    ctx.postMessage({
      id,
      ok: false,
      error: err instanceof Error ? err.message : String(err),
    });
  }
};

