  getThumbnailText,
  thumbnailFileMeta,
} from "@/components/file-thumbnail/thumbnail-text";

const CODE_THUMBNAIL_MAX_LINES = 60;
const CODE_THUMBNAIL_FONT_SIZE = 5;
const CODE_THUMBNAIL_LINE_HEIGHT = 1.5;
const CODE_THUMBNAIL_LINE_NUMBER_WIDTH_CLASS = "w-2.5";

export function CodeThumbnail({
  resource,
  thumbnailKey,
}: {
  resource: ViewerResource;
  thumbnailKey: string;
}) {
  const raw = useThumbnailResource(
    getThumbnailText(
      thumbnailFileMeta(resource),
      resource.content,
      thumbnailKey,
    ),
  );
  const text = React.useMemo(
    () => formatCodeThumbnailText(raw, resource.fileName, resource.mimeType),
    [raw, resource.fileName, resource.mimeType],
  );
  const lines = React.useMemo(
    () =>
      text
        .replace(/\r?\n$/, "")
        .split(/\r\n?|\n/)
        .slice(0, CODE_THUMBNAIL_MAX_LINES),
    [text],
  );

  return (
    <div
      data-slot="code-thumbnail"
      className="bg-code text-code-foreground absolute inset-0 overflow-hidden"
    >
      <div
        aria-hidden
        className={`absolute inset-y-0 left-0 ${CODE_THUMBNAIL_LINE_NUMBER_WIDTH_CLASS} bg-code-highlight`}
      />
      <div
        className="relative font-mono"
        style={{
          fontSize: CODE_THUMBNAIL_FONT_SIZE,
          lineHeight: CODE_THUMBNAIL_LINE_HEIGHT,
        }}
      >
        {lines.map((line, i) => (
          <div key={i} className="flex">
            <span
              className={`${CODE_THUMBNAIL_LINE_NUMBER_WIDTH_CLASS} text-code-number shrink-0 pr-px text-right select-none`}
            >
              {i + 1}
            </span>
            <span className="pl-0.5 whitespace-pre">{line || " "}</span>
          </div>
        ))}
      </div>
    </div>
  );
}

import type { ViewerDescriptor } from "@/lib/viewer-source";
import { extensionOf } from "@/lib/viewer-source";

const CODE_THUMBNAIL_EXTENSIONS = new Set([
  "bash",
  "c",
  "cc",
  "cjs",
  "cpp",
  "cs",
  "css",
  "env",
  "go",
  "graphql",
  "h",
  "ini",
  "java",
  "js",
  "json",
  "json5",
  "jsonl",
  "jsx",
  "kt",
  "less",
  "log",
  "lua",
  "mjs",
  "ndjson",
  "php",
  "pl",
  "proto",
  "py",
  "r",
  "rb",
  "rs",
  "scala",
  "scss",
  "sh",
  "sql",
  "svelte",
  "swift",
  "toml",
  "ts",
  "tsx",
  "vue",
  "xml",
  "yaml",
  "yml",
  "zsh",
]);

export function isCodeThumbnailDescriptor(
  descriptor: ViewerDescriptor,
): boolean {
  const extension = extensionOf(descriptor.displayName);
  if (extension && CODE_THUMBNAIL_EXTENSIONS.has(extension)) return true;

  const mime = descriptor.mimeType?.toLowerCase().split(";")[0].trim();
  return (
    mime === "application/json" ||
    mime === "application/xml" ||
    mime === "text/javascript" ||
    mime === "application/javascript" ||
    Boolean(mime?.endsWith("+json") || mime?.endsWith("+xml"))
  );
}

export function formatCodeThumbnailText(
  text: string,
  fileName: string,
  mimeType?: string,
) {
  if (!isStrictJson(fileName, mimeType)) return text;

  try {
    return JSON.stringify(JSON.parse(text), null, 2);
  } catch {
    return text;
  }
}

function isStrictJson(fileName: string, mimeType?: string) {
  const extension = extensionOf(fileName);
  if (extension === "json") return true;
  if (
    extension === "json5" ||
    extension === "jsonl" ||
    extension === "ndjson"
  ) {
    return false;
  }

  const mime = mimeType?.toLowerCase().split(";")[0].trim();
  return mime === "application/json" || Boolean(mime?.endsWith("+json"));
}

// Ambient shim for the `utif` package, which ships no type declarations
// (and has no @types/utif on npm). shadcn's registry build strips leading
// comments from source files, so an inline `@ts-expect-error` above the import
// does not survive into the published item — a real declaration is required for
// a fresh consumer install to typecheck. The decode workers cast the default
// export to their own local shapes, so an opaque `any` default is sufficient.
declare module "utif" {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const UTIF: any;
  export default UTIF;
}

import type * as DocxPreview from "docx-preview";

import {
  isViewerFormatError,
  ViewerFormatError,
  type ViewerFormatErrorMapperOptions,
} from "@/lib/viewer-errors";

export const DOCX_MIN_SCALE = 0.25;
export const DOCX_MAX_SCALE = 5;
export const DOCX_ZOOM_STEP = 1.2;

export const DEFAULT_DOCX_PAGE_WIDTH = 816;
export const DEFAULT_DOCX_PAGE_HEIGHT = 1056;

export const DOCX_RENDER_OPTIONS: Partial<DocxPreview.Options> = {
  inWrapper: true,
  breakPages: true,
  ignoreLastRenderedPageBreak: false,
  experimental: true,
  renderHeaders: true,
  renderFooters: true,
  renderFootnotes: true,
};

export const DOCX_SCOPED_STYLES = `
[data-slot="docx-viewer"] .docx-wrapper {
  background: transparent;
  padding: 0;
  gap: 1rem;
}
[data-slot="docx-viewer"] .docx-wrapper > section.docx {
  margin-bottom: 0;
  box-shadow: 0 0 0 1px var(--border), 0 1px 2px 0 rgb(0 0 0 / 0.05);
}`;

export function clampDocxScale(value: number) {
  return clamp(value, DOCX_MIN_SCALE, DOCX_MAX_SCALE);
}

export function normalizeDocxScale(value: number | null | undefined) {
  if (value == null) return null;
  if (Number.isNaN(value)) return 1;
  return clampDocxScale(value);
}

export function clamp(value: number, min: number, max: number) {
  return Math.min(max, Math.max(min, value));
}

export function positivePixel(value: number) {
  return Number.isFinite(value) && value > 0 ? value : null;
}

export function toDocxFormatError(
  error: unknown,
  options: ViewerFormatErrorMapperOptions,
): ViewerFormatError {
  if (isViewerFormatError(error)) return error;
  return new ViewerFormatError({
    format: "docx",
    kind: options.kind,
    message: options.message,
    cause: error,
  });
}

import { clamp } from "./docx-viewer-core";

export const DOCX_PAGE_GAP_PX = 16;
export const DOCX_VIEWER_PADDING_PX = 16;
export const DOCX_READING_MARKER_RATIO = 0.2;
export const DOCX_VIRTUAL_OVERSCAN_PX = 1000;
export const DOCX_FALLBACK_VIEWPORT_HEIGHT_PX = 768;

export interface DocxPageMetric {
  pageNumber: number;
  width: number;
  height: number;
  top: number;
  bottom: number;
}

export interface DocxPageLayout {
  pages: readonly DocxPageMetric[];
  totalHeight: number;
}

export interface DocxPageWindow {
  afterHeight: number;
  beforeHeight: number;
  endIndex: number;
  renderedBottom: number;
  renderedHeight: number;
  renderedTop: number;
  startIndex: number;
  stickyOffset: number;
}

export type DocxReadingAnchor =
  | {
      kind: "top";
    }
  | {
      kind: "page";
      pageNumber: number;
      yPercent: number;
    };

export function createDocxPageLayout(
  sizes: readonly (readonly [number, number])[],
  gap = DOCX_PAGE_GAP_PX,
): DocxPageLayout {
  let top = 0;
  const pages = sizes.map(([width, height], index) => {
    const page: DocxPageMetric = {
      pageNumber: index + 1,
      width,
      height,
      top,
      bottom: top + height,
    };
    top = page.bottom + gap;
    return page;
  });

  return {
    pages,
    totalHeight: pages.length ? pages[pages.length - 1]!.bottom : 0,
  };
}

export function findDocxPageByMarker({
  layout,
  scale,
  scrollTop,
  viewportHeight,
}: {
  layout: DocxPageLayout | null;
  scale: number;
  scrollTop: number;
  viewportHeight: number;
}) {
  const pages = layout?.pages;
  if (!pages?.length) return null;

  const marker = scrollTop + viewportHeight * DOCX_READING_MARKER_RATIO;
  const y = Math.max(0, (marker - DOCX_VIEWER_PADDING_PX) / safeScale(scale));
  let low = 0;
  let high = pages.length - 1;
  let current = pages[0]!;

  while (low <= high) {
    const mid = Math.floor((low + high) / 2);
    const page = pages[mid]!;
    if (page.top <= y) {
      current = page;
      low = mid + 1;
    } else {
      high = mid - 1;
    }
  }

  return current;
}

export function captureDocxReadingAnchorFromLayout({
  layout,
  scale,
  scrollTop,
  viewportHeight,
}: {
  layout: DocxPageLayout | null;
  scale: number;
  scrollTop: number;
  viewportHeight: number;
}): DocxReadingAnchor {
  if (scrollTop <= 0) return { kind: "top" };

  const page = findDocxPageByMarker({
    layout,
    scale,
    scrollTop,
    viewportHeight,
  });
  if (!page || page.height <= 0) return { kind: "top" };

  const marker = scrollTop + viewportHeight * DOCX_READING_MARKER_RATIO;
  const y = Math.max(0, (marker - DOCX_VIEWER_PADDING_PX) / safeScale(scale));

  return {
    kind: "page",
    pageNumber: page.pageNumber,
    yPercent: clamp((y - page.top) / page.height, 0, 1),
  };
}

export function restoreDocxReadingAnchorFromLayout({
  anchor,
  layout,
  maxScrollTop,
  scale,
  viewportHeight,
}: {
  anchor: DocxReadingAnchor;
  layout: DocxPageLayout | null;
  maxScrollTop: number;
  scale: number;
  viewportHeight: number;
}) {
  if (anchor.kind === "top") return 0;

  const page = layout?.pages[anchor.pageNumber - 1];
  if (!page || page.height <= 0) return null;

  const y = (page.top + page.height * anchor.yPercent) * safeScale(scale);
  const marker = viewportHeight * DOCX_READING_MARKER_RATIO;
  return clamp(DOCX_VIEWER_PADDING_PX + y - marker, 0, maxScrollTop);
}

export function createDocxPageWindowFromScroll({
  layout,
  overscanPx = DOCX_VIRTUAL_OVERSCAN_PX,
  scale,
  scrollTop,
  viewportHeight,
}: {
  layout: DocxPageLayout | null;
  overscanPx?: number;
  scale: number;
  scrollTop: number;
  viewportHeight: number;
}): DocxPageWindow {
  const pages = layout?.pages;
  if (!layout || !pages?.length) {
    return emptyDocxPageWindow();
  }

  const z = safeScale(scale);
  const viewHeight = safeViewportHeight(viewportHeight) / z;
  const overscan = Math.max(0, overscanPx) / z;
  const viewTop = Math.max(0, (scrollTop - DOCX_VIEWER_PADDING_PX) / z);
  const windowTop = Math.max(0, viewTop - overscan);
  const windowBottom = Math.min(
    layout.totalHeight,
    viewTop + viewHeight + overscan,
  );

  let startIndex = pages.findIndex((page) => page.bottom >= windowTop);
  if (startIndex === -1) startIndex = pages.length - 1;

  let endIndex = startIndex;
  while (
    endIndex < pages.length &&
    pages[endIndex]!.top <= Math.max(windowBottom, pages[startIndex]!.top)
  ) {
    endIndex += 1;
  }
  if (endIndex === startIndex)
    endIndex = Math.min(pages.length, startIndex + 1);

  return createDocxPageWindowFromRange({
    endIndex,
    layout,
    startIndex,
    viewportHeight: viewHeight,
  });
}

export function createDocxPageWindowForPage({
  layout,
  pageIndex,
  scale,
  viewportHeight,
}: {
  layout: DocxPageLayout | null;
  pageIndex: number;
  scale: number;
  viewportHeight: number;
}): DocxPageWindow {
  const pages = layout?.pages;
  if (!layout || !pages?.length) return emptyDocxPageWindow();
  const safePageIndex = clamp(Math.floor(pageIndex), 0, pages.length - 1);
  return createDocxPageWindowFromRange({
    endIndex: safePageIndex + 1,
    layout,
    startIndex: safePageIndex,
    viewportHeight: safeViewportHeight(viewportHeight) / safeScale(scale),
  });
}

function createDocxPageWindowFromRange({
  endIndex,
  layout,
  startIndex,
  viewportHeight,
}: {
  endIndex: number;
  layout: DocxPageLayout;
  startIndex: number;
  viewportHeight: number;
}): DocxPageWindow {
  const pages = layout.pages;
  const start = clamp(Math.floor(startIndex), 0, pages.length);
  const end = clamp(Math.ceil(endIndex), start, pages.length);
  const first = pages[start];
  const last = pages[end - 1];
  if (!first || !last) return emptyDocxPageWindow();

  const renderedTop = first.top;
  const renderedBottom = last.bottom;
  const renderedHeight = renderedBottom - renderedTop;

  return {
    afterHeight: Math.max(0, layout.totalHeight - renderedBottom),
    beforeHeight: renderedTop,
    endIndex: end,
    renderedBottom,
    renderedHeight,
    renderedTop,
    startIndex: start,
    stickyOffset: -Math.max(0, renderedHeight - Math.max(1, viewportHeight)),
  };
}

function emptyDocxPageWindow(): DocxPageWindow {
  return {
    afterHeight: 0,
    beforeHeight: 0,
    endIndex: 0,
    renderedBottom: 0,
    renderedHeight: 0,
    renderedTop: 0,
    startIndex: 0,
    stickyOffset: 0,
  };
}

function safeViewportHeight(value: number) {
  return Number.isFinite(value) && value > 0
    ? value
    : DOCX_FALLBACK_VIEWPORT_HEIGHT_PX;
}

function safeScale(scale: number) {
  return Number.isFinite(scale) && scale > 0 ? scale : 1;
}

import { lruGet, lruSet } from "./viewer-lru-cache";

export const DOCX_RENDER_CACHE_MAX_ENTRIES = 4;

export type DocxPageSize = readonly [number, number];

export interface DocxRenderCacheEntry {
  pageSizes: readonly DocxPageSize[];
  renderHost: HTMLElement;
}

export interface DocxRenderCacheHit {
  pageSizes: readonly DocxPageSize[];
  renderHost: HTMLElement;
}

const UNSAFE_DOCX_RENDER_CACHE_SELECTOR =
  "audio, canvas, embed, iframe, object, video";

const docxRenderCache = new Map<string, DocxRenderCacheEntry>();
const pendingDocxRenderCache = new Map<
  string,
  Promise<DocxRenderCacheEntry | null>
>();

export function readDocxRenderCache(key: string): DocxRenderCacheHit | null {
  const entry = lruGet(docxRenderCache, key);
  return entry ? cloneDocxRenderCacheEntry(entry) : null;
}

export function readPendingDocxRenderCache(
  key: string,
): Promise<DocxRenderCacheEntry | null> | null {
  return pendingDocxRenderCache.get(key) ?? null;
}

export function writePendingDocxRenderCache(
  key: string,
  promise: Promise<DocxRenderCacheEntry | null>,
) {
  pendingDocxRenderCache.set(key, promise);
  void promise
    .finally(() => {
      if (pendingDocxRenderCache.get(key) === promise) {
        pendingDocxRenderCache.delete(key);
      }
    })
    .catch(() => undefined);
}

export function writeDocxRenderCache({
  key,
  pageSizes,
  renderHost,
}: {
  key: string;
  pageSizes: readonly DocxPageSize[];
  renderHost: HTMLElement;
}): DocxRenderCacheEntry | null {
  if (
    pageSizes.length === 0 ||
    !renderHost.querySelector(".docx-wrapper > section.docx")
  ) {
    return null;
  }
  if (!canCacheDocxRenderHost(renderHost)) return null;

  const cachedRenderHost = renderHost.cloneNode(true);
  if (!(cachedRenderHost instanceof HTMLElement)) return null;

  const entry: DocxRenderCacheEntry = {
    pageSizes,
    renderHost: cachedRenderHost,
  };
  lruSet(docxRenderCache, key, entry, undefined, DOCX_RENDER_CACHE_MAX_ENTRIES);
  return entry;
}

export function cloneDocxRenderCacheEntry(
  entry: DocxRenderCacheEntry,
): DocxRenderCacheHit {
  return {
    pageSizes: entry.pageSizes,
    renderHost: entry.renderHost.cloneNode(true) as HTMLElement,
  };
}

export function resetDocxRenderCacheForTests() {
  docxRenderCache.clear();
  pendingDocxRenderCache.clear();
}

function canCacheDocxRenderHost(renderHost: HTMLElement) {
  return !renderHost.querySelector(UNSAFE_DOCX_RENDER_CACHE_SELECTOR);
}

import type * as DocxPreview from "docx-preview";

import { ViewerFormatError } from "@/lib/viewer-errors";

import {
  DEFAULT_DOCX_PAGE_HEIGHT,
  DEFAULT_DOCX_PAGE_WIDTH,
  DOCX_RENDER_OPTIONS,
  positivePixel,
} from "./docx-viewer-core";
import {
  createDocxPageLayout,
  type DocxPageLayout,
  type DocxPageWindow,
} from "./docx-viewer-layout";
import {
  readDocxRenderCache,
  readPendingDocxRenderCache,
  writeDocxRenderCache,
  writePendingDocxRenderCache,
  type DocxPageSize,
  type DocxRenderCacheHit,
} from "./docx-viewer-render-cache";

let docxPromise: Promise<typeof DocxPreview> | null = null;

export interface DocxRenderedDocument {
  after: HTMLDivElement;
  before: HTMLDivElement;
  mountedEnd: number;
  mountedStart: number;
  pageLayout: DocxPageLayout;
  pages: readonly HTMLElement[];
  sticky: HTMLElement;
  wrapper: HTMLElement;
}

type DocxRenderBuffer = ArrayBuffer | (() => ArrayBuffer);

export function loadDocxPreview() {
  if (!docxPromise) {
    docxPromise = import("docx-preview").catch((error) => {
      docxPromise = null;
      throw error;
    });
  }
  return docxPromise;
}

export async function renderDocxPreview(
  buffer: ArrayBuffer,
  docxPreviewPromise = loadDocxPreview(),
) {
  const { renderAsync } = await docxPreviewPromise;
  const renderHost = document.createElement("div");
  await renderAsync(buffer, renderHost, undefined, DOCX_RENDER_OPTIONS);
  return renderHost;
}

export async function renderCachedDocxPreview({
  buffer,
  cacheKey,
  docxPreviewPromise,
  getScale,
}: {
  buffer: DocxRenderBuffer;
  cacheKey: string;
  docxPreviewPromise?: Promise<typeof DocxPreview>;
  getScale: () => number;
}): Promise<DocxRenderCacheHit> {
  const cached = readDocxRenderCache(cacheKey);
  if (cached) return cached;

  const pending = readPendingDocxRenderCache(cacheKey);
  if (pending) {
    const pendingEntry = await pending;
    if (pendingEntry) {
      return {
        pageSizes: pendingEntry.pageSizes,
        renderHost: pendingEntry.renderHost.cloneNode(true) as HTMLElement,
      };
    }
  }

  const renderPromise = renderDocxPreview(
    resolveDocxRenderBuffer(buffer),
    docxPreviewPromise ?? loadDocxPreview(),
  ).then((renderHost) => {
    const pageSizes = collectDocxPageSizes(renderHost, getScale());
    const cacheEntry = writeDocxRenderCache({
      key: cacheKey,
      pageSizes,
      renderHost,
    });

    return { cacheEntry, pageSizes, renderHost };
  });
  writePendingDocxRenderCache(
    cacheKey,
    renderPromise.then((result) => result.cacheEntry),
  );

  const result = await renderPromise;
  return {
    pageSizes: result.pageSizes,
    renderHost: result.renderHost,
  };
}

function resolveDocxRenderBuffer(buffer: DocxRenderBuffer) {
  return typeof buffer === "function" ? buffer() : buffer;
}

export function commitDocxRender({
  host,
  pageSizes,
  renderHost,
  scale,
}: {
  host: HTMLElement;
  pageSizes?: readonly DocxPageSize[];
  renderHost: HTMLElement;
  scale: number;
}) {
  const wrapper = renderHost.querySelector<HTMLElement>(".docx-wrapper");
  if (!wrapper) {
    throw new ViewerFormatError({
      format: "docx",
      kind: "render_failed",
      message: "DOCX render produced no pages.",
    });
  }
  const pages = Array.from(
    renderHost.querySelectorAll<HTMLElement>(".docx-wrapper > section.docx"),
  );
  if (!pages.length) {
    throw new ViewerFormatError({
      format: "docx",
      kind: "render_failed",
      message: "DOCX render produced no pages.",
    });
  }
  const z = scale || 1;
  const sizes =
    pageSizes && pageSizes.length === pages.length
      ? pageSizes
      : pages.map((el) => pageSize(el, z));
  pages.forEach((el, i) => {
    el.dataset.pageNumber = String(i + 1);
    el.style.contentVisibility = "auto";
    const [width, height] = sizes[i]!;
    el.style.containIntrinsicSize = `${width}px ${height}px`;
  });
  const pageLayout = createDocxPageLayout(sizes);
  const before = document.createElement("div");
  const after = document.createElement("div");
  before.dataset.slot = "docx-sticky-before-buffer";
  wrapper.dataset.slot = "docx-sticky-window";
  after.dataset.slot = "docx-sticky-after-buffer";
  before.setAttribute("aria-hidden", "true");
  after.setAttribute("aria-hidden", "true");
  wrapper.style.position = "sticky";
  wrapper.style.left = "0";
  wrapper.style.overflow = "visible";
  wrapper.style.width = "100%";

  const staticNodes = Array.from(renderHost.childNodes).filter(
    (node) => node !== wrapper,
  );
  wrapper.replaceChildren();
  host.replaceChildren(...staticNodes, before, wrapper, after);

  const virtualDocument: DocxRenderedDocument = {
    after,
    before,
    mountedEnd: 0,
    mountedStart: 0,
    pageLayout,
    pages,
    sticky: wrapper,
    wrapper,
  };
  return {
    numPages: pages.length,
    pageWidth: pages.length ? sizes[0][0] : null,
    pageLayout,
    virtualDocument,
  };
}

export function projectDocxPages(
  document: DocxRenderedDocument,
  window: DocxPageWindow,
) {
  document.before.style.height = `${window.beforeHeight}px`;
  document.after.style.height = `${window.afterHeight}px`;
  document.sticky.style.top = `${window.stickyOffset}px`;
  document.sticky.style.bottom = `${window.stickyOffset}px`;
  document.sticky.style.height = `${window.renderedHeight}px`;

  const start = window.startIndex;
  const end = window.endIndex;
  if (start === document.mountedStart && end === document.mountedEnd) return;

  if (
    document.mountedEnd <= document.mountedStart ||
    end <= start ||
    end <= document.mountedStart ||
    start >= document.mountedEnd
  ) {
    document.wrapper.replaceChildren(...document.pages.slice(start, end));
    document.mountedStart = start;
    document.mountedEnd = end;
    return;
  }

  for (
    let index = document.mountedStart;
    index < Math.min(start, document.mountedEnd);
    index += 1
  ) {
    document.pages[index]?.remove();
  }
  for (
    let index = Math.max(end, document.mountedStart);
    index < document.mountedEnd;
    index += 1
  ) {
    document.pages[index]?.remove();
  }

  if (start < document.mountedStart) {
    const fragment = globalThis.document.createDocumentFragment();
    for (let index = start; index < document.mountedStart; index += 1) {
      const page = document.pages[index];
      if (page) fragment.append(page);
    }
    document.wrapper.insertBefore(fragment, document.wrapper.firstChild);
  }

  if (end > document.mountedEnd) {
    const fragment = globalThis.document.createDocumentFragment();
    for (
      let index = Math.max(document.mountedEnd, start);
      index < end;
      index += 1
    ) {
      const page = document.pages[index];
      if (page) fragment.append(page);
    }
    document.wrapper.append(fragment);
  }

  document.mountedStart = start;
  document.mountedEnd = end;
}

function collectDocxPageSizes(
  renderHost: HTMLElement,
  scale: number,
): readonly DocxPageSize[] {
  const pages = Array.from(
    renderHost.querySelectorAll<HTMLElement>(".docx-wrapper > section.docx"),
  );
  const z = scale || 1;
  return pages.map((el) => pageSize(el, z));
}

function pageSize(el: HTMLElement, scale: number) {
  const styledWidth = positivePixel(Math.round(cssLengthToPx(el.style.width)));
  const styledHeight = positivePixel(
    Math.round(
      cssLengthToPx(el.style.height) || cssLengthToPx(el.style.minHeight),
    ),
  );
  if (styledWidth && styledHeight) {
    return [styledWidth, styledHeight] as const;
  }

  const r = el.getBoundingClientRect();
  const width = positivePixel(Math.round(r.width / scale));
  const height = positivePixel(Math.round(r.height / scale));
  return [
    styledWidth ?? width ?? DEFAULT_DOCX_PAGE_WIDTH,
    styledHeight ?? height ?? DEFAULT_DOCX_PAGE_HEIGHT,
  ] as const;
}

function cssLengthToPx(value: string) {
  const match = value.trim().match(/^(-?\d*\.?\d+)(px|pt|in|cm|mm|pc)?$/i);
  if (!match) return 0;

  const amount = Number(match[1]);
  if (!Number.isFinite(amount) || amount <= 0) return 0;

  const unit = (match[2] ?? "px").toLowerCase();
  if (unit === "px") return amount;
  if (unit === "pt") return (amount * 96) / 72;
  if (unit === "in") return amount * 96;
  if (unit === "cm") return (amount * 96) / 2.54;
  if (unit === "mm") return (amount * 96) / 25.4;
  if (unit === "pc") return amount * 16;
  return 0;
}

export function getPdfCanvasPixelSize(
  cssSize: number,
  devicePixelRatio: number,
) {
  if (
    !Number.isFinite(cssSize) ||
    !Number.isFinite(devicePixelRatio) ||
    cssSize <= 0 ||
    devicePixelRatio <= 0
  ) {
    return 1;
  }
  return Math.max(1, Math.floor(cssSize * devicePixelRatio));
}

import { useKeyedMountEffect } from "@/hooks/use-keyed-mount-effect";
import { joinEffectKey } from "@/lib/effect-key";

export const PDF_RENDERED_PAGE_CACHE_MAX_ENTRIES = 16;
export const PDF_RENDERED_PAGE_CACHE_MAX_PIXELS = 24_000_000;
// Only close lower-resolution renders of the same page may be stretched as
// resize previews; thumbnail-resolution bitmaps below this ratio would blur.
export const PDF_RENDERED_PAGE_PREVIEW_MIN_SCALE_RATIO = 0.5;

export type PdfRenderedPageSignature = {
  documentKey: string;
  pageNumber: number;
  scale: number;
  rotation: number;
  devicePixelRatio: number;
  viewportWidth: number;
  viewportHeight: number;
};

export type PdfRenderedPageCache = {
  clock: number;
  entries: Map<string, PdfRenderedPageCacheEntry>;
  resetKey: unknown;
};

export type PdfRenderedPageCacheEntry = PdfRenderedPageSignature & {
  canvas: HTMLCanvasElement;
  lastUsed: number;
  pixels: number;
};

type PdfRenderedPageCacheRecord = {
  cache: PdfRenderedPageCache;
  retainCount: number;
  resetKey: unknown;
};

const objectCacheRecords = new WeakMap<object, PdfRenderedPageCacheRecord>();
const primitiveCacheRecords = new Map<unknown, PdfRenderedPageCacheRecord>();

export function createPdfRenderedPageCache(
  resetKey: unknown,
): PdfRenderedPageCache {
  return {
    clock: 0,
    entries: new Map(),
    resetKey,
  };
}

export function usePdfRenderedPageCache(resetKey: unknown) {
  const record = getPdfRenderedPageCacheRecord(resetKey);

  useKeyedMountEffect(joinEffectKey([record]), () => {
    record.retainCount += 1;
    return () => releasePdfRenderedPageCacheRecord(record);
  });

  return record.cache;
}

export function readPdfRenderedPageCache(
  cache: PdfRenderedPageCache | undefined,
  requested: PdfRenderedPageSignature,
) {
  if (!cache) return null;

  let bestEntry: PdfRenderedPageCacheEntry | null = null;
  for (const entry of cache.entries.values()) {
    if (!doesRenderedPageSatisfyRequest(entry, requested)) continue;
    if (
      !bestEntry ||
      entry.pixels < bestEntry.pixels ||
      (entry.pixels === bestEntry.pixels && entry.lastUsed > bestEntry.lastUsed)
    ) {
      bestEntry = entry;
    }
  }

  if (!bestEntry) return null;
  cache.clock += 1;
  bestEntry.lastUsed = cache.clock;
  return bestEntry;
}

export function readPdfRenderedPageCachePreview(
  cache: PdfRenderedPageCache | undefined,
  requested: PdfRenderedPageSignature,
) {
  if (!cache) return null;

  let bestEntry: PdfRenderedPageCacheEntry | null = null;
  for (const entry of cache.entries.values()) {
    if (!doesRenderedPageMatchPreview(entry, requested)) continue;
    if (!bestEntry || entry.pixels > bestEntry.pixels) {
      bestEntry = entry;
    }
  }

  if (!bestEntry) return null;
  cache.clock += 1;
  bestEntry.lastUsed = cache.clock;
  return bestEntry;
}

export function writePdfRenderedPageCache({
  cache,
  rendered,
  sourceCanvas,
}: {
  cache: PdfRenderedPageCache | undefined;
  rendered: PdfRenderedPageSignature;
  sourceCanvas: HTMLCanvasElement;
}) {
  if (!cache || sourceCanvas.width <= 0 || sourceCanvas.height <= 0) return;

  const canvas = document.createElement("canvas");
  canvas.width = sourceCanvas.width;
  canvas.height = sourceCanvas.height;
  const context = canvas.getContext("2d");
  if (!context || typeof context.drawImage !== "function") return;

  context.drawImage(sourceCanvas, 0, 0);
  cache.clock += 1;
  const key = getPdfRenderedPageCacheKey(rendered);
  cache.entries.set(key, {
    ...rendered,
    canvas,
    lastUsed: cache.clock,
    pixels: canvas.width * canvas.height,
  });
  evictPdfRenderedPageCache(cache, key);
}

export function clearPdfRenderedPageCache(cache: PdfRenderedPageCache) {
  cache.clock = 0;
  cache.entries.clear();
}

function evictPdfRenderedPageCache(
  cache: PdfRenderedPageCache,
  retainedKey: string,
) {
  let totalPixels = getTotalCachedPixels(cache);

  while (
    cache.entries.size > PDF_RENDERED_PAGE_CACHE_MAX_ENTRIES ||
    totalPixels > PDF_RENDERED_PAGE_CACHE_MAX_PIXELS
  ) {
    const evicted = findPdfRenderedPageCacheEviction(cache, retainedKey);
    if (!evicted) return;

    totalPixels -= evicted.entry.pixels;
    cache.entries.delete(evicted.key);
  }
}

function findPdfRenderedPageCacheEviction(
  cache: PdfRenderedPageCache,
  retainedKey: string,
) {
  let oldest: { key: string; entry: PdfRenderedPageCacheEntry } | null = null;

  for (const [key, entry] of cache.entries) {
    if (key === retainedKey) continue;
    if (!oldest || entry.lastUsed < oldest.entry.lastUsed) {
      oldest = { key, entry };
    }
  }

  return oldest;
}

function getTotalCachedPixels(cache: PdfRenderedPageCache) {
  let pixels = 0;
  for (const entry of cache.entries.values()) {
    pixels += entry.pixels;
  }
  return pixels;
}

function doesRenderedPageSatisfyRequest(
  rendered: PdfRenderedPageSignature,
  requested: PdfRenderedPageSignature,
) {
  return (
    rendered.documentKey === requested.documentKey &&
    rendered.pageNumber === requested.pageNumber &&
    rendered.rotation === requested.rotation &&
    rendered.scale >= requested.scale &&
    rendered.viewportWidth >= requested.viewportWidth &&
    rendered.viewportHeight >= requested.viewportHeight &&
    hasMatchingPageAspectRatio(rendered, requested) &&
    rendered.devicePixelRatio >= requested.devicePixelRatio
  );
}

function doesRenderedPageMatchPreview(
  rendered: PdfRenderedPageSignature,
  requested: PdfRenderedPageSignature,
) {
  return (
    rendered.documentKey === requested.documentKey &&
    rendered.pageNumber === requested.pageNumber &&
    rendered.rotation === requested.rotation &&
    rendered.viewportWidth >=
      requested.viewportWidth * PDF_RENDERED_PAGE_PREVIEW_MIN_SCALE_RATIO &&
    rendered.viewportHeight >=
      requested.viewportHeight * PDF_RENDERED_PAGE_PREVIEW_MIN_SCALE_RATIO &&
    hasMatchingPageAspectRatio(rendered, requested)
  );
}

function getPdfRenderedPageCacheKey(rendered: PdfRenderedPageSignature) {
  return [
    rendered.documentKey,
    rendered.pageNumber,
    rendered.scale,
    rendered.rotation,
    rendered.devicePixelRatio,
    rendered.viewportWidth,
    rendered.viewportHeight,
  ].join(":");
}

function getPdfRenderedPageCacheRecord(
  resetKey: unknown,
): PdfRenderedPageCacheRecord {
  const records = isObjectCacheKey(resetKey)
    ? objectCacheRecords
    : primitiveCacheRecords;
  const cached = records.get(resetKey as never);
  if (cached) return cached;

  const record: PdfRenderedPageCacheRecord = {
    cache: createPdfRenderedPageCache(resetKey),
    retainCount: 0,
    resetKey,
  };
  records.set(resetKey as never, record);
  return record;
}

function releasePdfRenderedPageCacheRecord(record: PdfRenderedPageCacheRecord) {
  record.retainCount = Math.max(0, record.retainCount - 1);
  if (record.retainCount > 0) return;

  clearPdfRenderedPageCache(record.cache);
  if (isObjectCacheKey(record.resetKey)) {
    objectCacheRecords.delete(record.resetKey);
  } else {
    primitiveCacheRecords.delete(record.resetKey);
  }
}

function isObjectCacheKey(value: unknown): value is object {
  return (
    (typeof value === "object" && value !== null) || typeof value === "function"
  );
}

function hasMatchingPageAspectRatio(
  rendered: PdfRenderedPageSignature,
  requested: PdfRenderedPageSignature,
) {
  const renderedRatio = rendered.viewportWidth / rendered.viewportHeight;
  const requestedRatio = requested.viewportWidth / requested.viewportHeight;
  return Math.abs(renderedRatio - requestedRatio) < 0.0001;
}
